const BZIP2_WASM_B64 = "";

let bz2ModuleInstance = null;

async function getBz2Module() {
  if (bz2ModuleInstance) return bz2ModuleInstance;

  setWorkProgress("Starting BZ2 Wasm.", 0, 0);
  const binaryString = atob(BZIP2_WASM_B64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  const moduleConfig = {
    wasmBinary: bytes.buffer,
    locateFile: (path) => {
      if (path.endsWith('.wasm')) {
        const blob = new Blob([bytes], { type: 'application/wasm' });
        return URL.createObjectURL(blob);
      }
      return path;
    }
  };

  bz2ModuleInstance = await createBzip2Module(moduleConfig);
  return bz2ModuleInstance;
}

