async function inflateBZ2(data) {
  const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);

  // Quick header check
  if (bytes.length < 3 || bytes[0] !== 0x42 || bytes[1] !== 0x5a || bytes[2] !== 0x68) {
    console.log("[BZ2] Not a BZ2 stream, passing through raw data. Size:", bytes.length);
    return bytes;
  }

  let Module = null;
  let srcPtr = 0;
  let outLenPtr = 0;
  let destPtr = 0;

  // --- TIER 1: Try Blazing-Fast WASM ---
  try {
    setWorkProgress("Inflating BZ2 Data via WASM", 0, 0);
    console.log("[BZ2-WASM] Starting decompression. Input size:", bytes.length);

    Module = await getBz2Module();
    
    srcPtr = Module._malloc(bytes.length);
    const heap = Module.HEAPU8 || new Uint8Array(Module.wasmMemory.buffer);
    heap.set(bytes, srcPtr);

    outLenPtr = Module._malloc(4);
    destPtr = Module._bz2_decompress_wrapper(srcPtr, bytes.length, outLenPtr);

    if (!destPtr) {
      throw new Error("C wrapper returned null pointer.");
    }

    const finalLen = Module.getValue(outLenPtr, 'i32');
    const currentHeap = Module.HEAPU8 || new Uint8Array(Module.wasmMemory.buffer);
    
    const decompressed = new Uint8Array(finalLen);
    decompressed.set(new Uint8Array(currentHeap.buffer, destPtr, finalLen));

    console.log("[BZ2-WASM] Decompression finished successfully. Output size:", decompressed.length);
    return decompressed;

  } catch (wasmError) {
    console.warn("[BZ2-WASM] WASM decompression failed, falling back to Pure JS engine...", wasmError);
    
    try {
      return await inflateBZ2_JS(bytes);
    } catch (jsError) {
      console.warn("[BZ2-JS] Pure JS decompression also failed, passing through raw bytes:", jsError);
      
      return bytes;
    }

  } finally {
    if (Module) {
      if (destPtr) Module._bz2_free(destPtr);
      if (srcPtr) Module._free(srcPtr);
      if (outLenPtr) Module._free(outLenPtr);
    }
  }
}
